(()=>{(function(){"use strict";var e=[[19.1,35.1],[24.87,20.88],[39.95,7.1],[16.64,-20.01],[5.24,-40.47],[-27.35,-28.41],[-33.34,.07],[-12.07,21.25],[-5.54,39.67]],o=[-4,8,-7,5,10,-6,8,-9,0];function c(t,a,l,s){return[e[t][0]+(a||0),o[t]+(l||0),e[t][1]+(s||0)]}var n={az:303.7,el:-20,dist:17},p=[{num:"壹",title:"人",hue:"#d98e5f",pos:c(0),viewDy:-172,cam:{az:208.6,el:-20,dist:17},rotY:-95.1,line:"你以为的「自己」，是好几个「我」织出来的——意识在头顶，觉知在眉心，自我是面孔，内我是胸腔里跳动的光，外我朝世界伸出手。",model:"acts/act1.glb",concepts:["concept-004","concept-031","concept-006","concept-020","concept-007","concept-008","concept-018","concept-034","concept-041"]},{num:"贰",title:"现实是搭出来的",hue:"#9a8be8",pos:c(1),viewDy:-179,cam:{az:223.5,el:-12,dist:16.3},tgtOff:[-.77,4,.92],rotY:96.2,line:"你脚下的世界不是铁板一块。物质实相是一层伪装，底下另有一套架构在承重——这一章拆现实的骨架。",model:"acts/act2_temple.glb",concepts:["concept-003","concept-014","concept-015","concept-016","concept-036","concept-037","concept-009","concept-052","concept-048","concept-058"]},{num:"叁",title:"五官之外的整套感官",hue:"#c07fc9",pos:c(2),viewDy:-160,cam:{az:262.9,el:-16.1,dist:17},rotY:-80.7,line:"如果肉体感官只是延伸，被延伸的母体是什么？这一章讲你天生就有、却从没上过课的那整套感知。",model:"acts/act3_seer.glb",concepts:["concept-020","concept-021","concept-022","concept-042","concept-043","concept-019","concept-045","concept-026","concept-040","concept-033"]},{num:"肆",title:"思想、情感与活力",hue:"#e0a37c",pos:c(3),viewDy:-137,cam:{az:298,el:-32,dist:16.1},tgtOff:[-.54,-3.4,-.69],tiltX:-160,line:"在这里，思想是东西，情感是方向，活力是燃料——这一章看你内在到底在流动着什么。",model:"acts/act4_prayer_wheel_v2.glb",concepts:["concept-028","concept-029","concept-010","concept-061","concept-030","concept-032","concept-001","concept-046","concept-047"]},{num:"伍",title:"梦、时间与当下",hue:"#6fc4b0",pos:c(4),viewDy:-131,cam:{az:332.4,el:-7.5,dist:16},tgtOff:[.06,3.3,-.33],line:"钟表时间只是披在外面的晚礼服。梦有它的场地，当下有它的宽度，而你身上一直带着一个力量之点。",model:"acts/act5_dreamwatch.glb",concepts:["concept-005","concept-023","concept-025","concept-035","concept-057","concept-027","concept-017","concept-049"]},{num:"陆",title:"更大的自己",hue:"#6fa8dc",pos:c(5),viewDy:-136,cam:{az:43.5,el:-30,dist:14.1},tgtOff:[.05,3.6,-.39],rotY:85.6,line:"把镜头从一生拉开：灵魂、实体、超灵……「我」比你知道的大得多。",model:"acts/act6_door.glb",concepts:["concept-012","concept-039","concept-011","concept-050","concept-053","concept-054","concept-055","concept-056"]},{num:"柒",title:"信什么，就活进什么",hue:"#d4a05a",pos:c(6),viewDy:53,cam:{az:81.9,el:-35.3,dist:21.7},tgtOff:[-.26,3.3,.73],rotY:51.3,line:"信念不是观点，是施工图纸。这一章讲你如何住进自己信的实相里——以及，怎么改图纸。",model:"acts/act7_sphere.glb",concepts:["concept-013","concept-002","concept-059","concept-060","concept-063"]},{num:"捌",title:"门之后",hue:"#c9d2e8",pos:c(7),viewDy:-91,cam:{az:149,el:-20.3,dist:17},rotY:148.8,line:"最后一章关于死亡、轮回与或然的自己。不是终点介绍——这趟旅程本来就是环形的。",model:"acts/act8_bodhisattva.glb",concepts:["concept-062","concept-024","concept-051"]},{num:"玖",title:"待定",hue:"#e0708a",pos:c(8),viewDy:106,cam:{az:172.1,el:-28,dist:27},rotY:133.3,line:"（本章标题与文案待定，先把隐喻物挂上。）",model:"acts/act9_lotus.glb",concepts:[]}];window.ACTS=p,window.CAM=n})();})();
